import { useState } from 'react';
import type { FormEvent } from 'react';
import {
  JxStepper,
  JxInputField,
  JxSelect,
  JxTextareaField,
  JxButton,
  JxDivider,
  JxAlert,
} from '@jinx-ui/react';

interface RegistrationData {
  name: string;
  email: string;
  phone: string;
  country: string;
  city: string;
  street: string;
  note: string;
}

const steps = [{ label: 'Контакты' }, { label: 'Адрес' }, { label: 'Проверка' }];

const countries = [
  { value: 'ru', label: 'Россия' },
  { value: 'kz', label: 'Казахстан' },
  { value: 'by', label: 'Беларусь' },
  { value: 'am', label: 'Армения' },
];

const emptyData: RegistrationData = {
  name: '',
  email: '',
  phone: '',
  country: '',
  city: '',
  street: '',
  note: '',
};

export default function RegistrationWizard({
  onSubmit,
}: {
  onSubmit: (data: RegistrationData) => void;
}) {
  const [step, setStep] = useState(0);
  const [data, setData] = useState<RegistrationData>(emptyData);
  const [touched, setTouched] = useState(false);

  const set = <K extends keyof RegistrationData>(key: K, value: RegistrationData[K]) => {
    setData((prev) => ({ ...prev, [key]: value }));
  };

  const nameError = !data.name.trim() ? 'Укажите имя' : undefined;
  const emailError = !data.email.trim()
    ? 'Укажите адрес почты'
    : !data.email.includes('@')
      ? 'Адрес должен содержать символ @'
      : undefined;
  const countryError = !data.country ? 'Выберите страну' : undefined;
  const cityError = !data.city.trim() ? 'Укажите город' : undefined;
  const streetError = !data.street.trim() ? 'Укажите улицу и дом' : undefined;

  const stepErrors: Array<Array<string | undefined>> = [
    [nameError, emailError],
    [countryError, cityError, streetError],
    [],
  ];
  const stepValid = stepErrors[step].every((error) => !error);
  const show = (error: string | undefined) => (touched ? error : undefined);

  const goNext = () => {
    if (!stepValid) {
      setTouched(true);
      return;
    }
    setTouched(false);
    setStep((current) => Math.min(current + 1, steps.length - 1));
  };

  const goBack = () => {
    setTouched(false);
    setStep((current) => Math.max(current - 1, 0));
  };

  const submit = (event: FormEvent<HTMLFormElement>) => {
    event.preventDefault();
    if (step < steps.length - 1) {
      goNext();
      return;
    }
    onSubmit(data);
  };

  const countryLabel = countries.find((item) => item.value === data.country)?.label ?? '—';

  return (
    <form
      onSubmit={submit}
      style={{ display: 'grid', gap: '24px', fontFamily: 'var(--jx-font-sans)', color: 'var(--jx-text)' }}
    >
      <JxStepper steps={steps} current={step} />

      {step === 0 && (
        <div style={{ display: 'grid', gap: '12px' }}>
          <JxInputField
            label="Имя и фамилия"
            required
            autoComplete="name"
            value={data.name}
            onChange={(event) => set('name', event.target.value)}
            errorText={show(nameError)}
          />
          <JxInputField
            label="Электронная почта"
            type="email"
            required
            autoComplete="email"
            value={data.email}
            onChange={(event) => set('email', event.target.value)}
            errorText={show(emailError)}
          />
          <JxInputField
            label="Телефон"
            type="tel"
            prefix="+7"
            autoComplete="tel"
            placeholder="900 000-00-00"
            helperText="Необязательно, нужен только для доставки"
            value={data.phone}
            onChange={(event) => set('phone', event.target.value)}
          />
        </div>
      )}

      {step === 1 && (
        <div style={{ display: 'grid', gap: '12px' }}>
          <JxSelect
            label="Страна"
            placeholder="Выберите страну"
            options={countries}
            value={data.country}
            onValueChange={(value) => set('country', value)}
          />
          {show(countryError) && <JxAlert intent="danger" title="Страна не выбрана">{countryError}</JxAlert>}
          <JxInputField
            label="Город"
            required
            autoComplete="address-level2"
            value={data.city}
            onChange={(event) => set('city', event.target.value)}
            errorText={show(cityError)}
          />
          <JxInputField
            label="Улица и дом"
            required
            autoComplete="street-address"
            value={data.street}
            onChange={(event) => set('street', event.target.value)}
            errorText={show(streetError)}
          />
          <JxTextareaField
            label="Комментарий для курьера"
            rows={3}
            maxLength={300}
            value={data.note}
            onChange={(event) => set('note', event.target.value)}
            helperText={`${data.note.length}/300`}
          />
        </div>
      )}

      {step === 2 && (
        <div style={{ display: 'grid', gap: '12px' }}>
          <JxAlert intent="info" title="Проверьте данные">
            После отправки изменить анкету можно будет только через поддержку.
          </JxAlert>
          <JxDivider label="Контакты" />
          <dl style={{ display: 'grid', gap: '8px', margin: 0 }}>
            <div style={{ display: 'flex', gap: '12px', justifyContent: 'space-between' }}>
              <dt style={{ color: 'var(--jx-text-2)' }}>Имя</dt>
              <dd style={{ margin: 0, textAlign: 'right', wordBreak: 'break-word' }}>{data.name}</dd>
            </div>
            <div style={{ display: 'flex', gap: '12px', justifyContent: 'space-between' }}>
              <dt style={{ color: 'var(--jx-text-2)' }}>Почта</dt>
              <dd style={{ margin: 0, textAlign: 'right', wordBreak: 'break-word' }}>{data.email}</dd>
            </div>
            <div style={{ display: 'flex', gap: '12px', justifyContent: 'space-between' }}>
              <dt style={{ color: 'var(--jx-text-2)' }}>Телефон</dt>
              <dd style={{ margin: 0, textAlign: 'right' }}>{data.phone ? `+7 ${data.phone}` : '—'}</dd>
            </div>
          </dl>
          <JxDivider label="Адрес" />
          <dl style={{ display: 'grid', gap: '8px', margin: 0 }}>
            <div style={{ display: 'flex', gap: '12px', justifyContent: 'space-between' }}>
              <dt style={{ color: 'var(--jx-text-2)' }}>Страна</dt>
              <dd style={{ margin: 0, textAlign: 'right' }}>{countryLabel}</dd>
            </div>
            <div style={{ display: 'flex', gap: '12px', justifyContent: 'space-between' }}>
              <dt style={{ color: 'var(--jx-text-2)' }}>Город</dt>
              <dd style={{ margin: 0, textAlign: 'right', wordBreak: 'break-word' }}>{data.city}</dd>
            </div>
            <div style={{ display: 'flex', gap: '12px', justifyContent: 'space-between' }}>
              <dt style={{ color: 'var(--jx-text-2)' }}>Улица и дом</dt>
              <dd style={{ margin: 0, textAlign: 'right', wordBreak: 'break-word' }}>{data.street}</dd>
            </div>
            {data.note && (
              <div style={{ display: 'flex', gap: '12px', justifyContent: 'space-between' }}>
                <dt style={{ color: 'var(--jx-text-2)' }}>Комментарий</dt>
                <dd style={{ margin: 0, textAlign: 'right', wordBreak: 'break-word' }}>{data.note}</dd>
              </div>
            )}
          </dl>
        </div>
      )}

      <div style={{ display: 'flex', gap: '8px', justifyContent: 'flex-end' }}>
        <JxButton type="button" variant="ghost" disabled={step === 0} onClick={goBack}>
          Назад
        </JxButton>
        {step < steps.length - 1 ? (
          <JxButton type="button" variant="primary" onClick={goNext}>
            Дальше
          </JxButton>
        ) : (
          <JxButton type="submit" variant="primary">
            Отправить
          </JxButton>
        )}
      </div>
    </form>
  );
}

